// Real Compiled Midnight Compact Circuit Simulator Tests
//
// Executes the ACTUAL compiled output (`contracts/managed/leaseproof/contract/index.js`)
// generated by `compact compile contracts/leaseproof.compact contracts/managed/leaseproof`
// using official `@midnight-ntwrk/compact-runtime` and `contracts/witnesses.ts`.

import { existsSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { describe, expect, it } from "vitest";
import {
  CompactTypeBytes,
  CompactTypeVector,
  convertBigintToBytes,
  createCircuitContext,
  createConstructorContext,
  persistentHash,
  sampleContractAddress,
  sampleUserAddress,
} from "@midnight-ntwrk/compact-runtime";
import {
  createInitialPrivateState,
  padBytes32,
  witnesses,
  type LeaseProofPrivateState,
} from "../witnesses";

const COMPILED_CONTRACT_PATH = path.resolve(
  process.cwd(),
  "contracts/managed/leaseproof/contract/index.js"
);
const HAS_COMPILED_ARTIFACT = existsSync(COMPILED_CONTRACT_PATH);
const IS_CI = process.env.CI === "true";

const vec2Bytes32 = new CompactTypeVector(2, new CompactTypeBytes(32));
const vec8Bytes32 = new CompactTypeVector(8, new CompactTypeBytes(32));

function computeAdminCommit(secret: Uint8Array): Uint8Array {
  return persistentHash(vec2Bytes32, [padBytes32("leaseproof:admin"), secret]);
}

function computeIssuerKeyCommit(secret: Uint8Array): Uint8Array {
  return persistentHash(vec2Bytes32, [padBytes32("leaseproof:issuer"), secret]);
}

function computeCompactAttestationCommit(params: {
  issuerId: Uint8Array;
  applicantId: Uint8Array;
  currency: bigint;
  income: bigint;
  balance: bigint;
  attExpiry: bigint;
  nonce: Uint8Array;
}): Uint8Array {
  return persistentHash(vec8Bytes32, [
    padBytes32("leaseproof:attest"),
    params.issuerId,
    params.applicantId,
    convertBigintToBytes(32, params.currency, "currency"),
    convertBigintToBytes(32, params.income, "income"),
    convertBigintToBytes(32, params.balance, "balance"),
    convertBigintToBytes(32, params.attExpiry, "attExpiry"),
    params.nonce,
  ]);
}

describe("Compiled Midnight Compact Contract (contracts/leaseproof.compact)", () => {
  if (!HAS_COMPILED_ARTIFACT && !IS_CI) {
    it.skip("Skipped locally on Windows without compiled artifact (runs automatically in Ubuntu Linux CI)", () => {});
    return;
  }

  it("compiles and executes all 7 hardened circuits + adversarial rejections on @midnight-ntwrk/compact-runtime", async () => {
    expect(HAS_COMPILED_ARTIFACT).toBe(true);

    // Dynamically import the real `compact compile` generated JS contract module
    const compiled = await import(pathToFileURL(COMPILED_CONTRACT_PATH).href);
    const { Contract, ledger } = compiled;

    const contract = new Contract(witnesses);
    const contractAddress = sampleContractAddress();
    const coinPublicKey = sampleUserAddress();

    const adminSecret = padBytes32("admin-secret-wave3");
    const wrongAdminSecret = padBytes32("attacker-fake-admin");
    const issuerSecret = padBytes32("argyle-signing-secret");
    const wrongIssuerSecret = padBytes32("forger-issuer-secret");
    const tenantSecret = padBytes32("maya-revocation-secret");
    const strangerSecret = padBytes32("stranger-revoke-secret");

    const issuerId = padBytes32("argyle-payroll");
    const listingId = padBytes32("apt-soho-204");
    const applicantId = padBytes32("kyc-maya-ssn-9042");
    const nonce = padBytes32("nonce-argyle-0001");

    const initialEpoch = BigInt(1_795_600_000);
    const validAttExpiry = initialEpoch + BigInt(86_400) * BigInt(30);

    const adminCommit = computeAdminCommit(adminSecret);
    const issuerKeyCommit = computeIssuerKeyCommit(issuerSecret);

    // 1. Deploy via constructor(initialAdminCommit, initialEpoch)
    let privateState: LeaseProofPrivateState = createInitialPrivateState({ adminSecret });
    const initResult = await contract.initialState(
      createConstructorContext(privateState, coinPublicKey),
      adminCommit,
      initialEpoch
    );
    let currentState = initResult.currentContractState;
    let zswapState = initResult.currentZswapLocalState;
    privateState = initResult.currentPrivateState;

    const callCircuit = async (
      circuitId: string,
      ps: LeaseProofPrivateState,
      ...args: unknown[]
    ) => {
      const ctx = createCircuitContext({
        circuitId,
        contractAddress,
        coinPublicKeyOrZswapState: zswapState,
        contractState: currentState,
        privateState: ps,
      });
      const res = await contract.impureCircuits[circuitId](ctx, ...args);
      currentState = res.context.callContext.currentQueryContext.state;
      zswapState = res.context.callContext.currentZswapLocalState ?? zswapState;
      return res;
    };

    const readLedger = () => ledger(currentState.data ?? currentState);

    // Check initial ledger state
    expect(readLedger().currentLedgerEpoch).toBe(initialEpoch);

    // 2. Reject UNAUTHORIZED_ADMIN on registerIssuer
    await expect(
      callCircuit(
        "registerIssuer",
        createInitialPrivateState({ adminSecret: wrongAdminSecret }),
        issuerId,
        issuerKeyCommit
      )
    ).rejects.toThrow(/UNAUTHORIZED_ADMIN/);

    // 3. Admin registers Argyle issuer
    await callCircuit(
      "registerIssuer",
      createInitialPrivateState({ adminSecret }),
      issuerId,
      issuerKeyCommit
    );
    expect(readLedger().trustedIssuers.lookup(issuerId)).toBe(BigInt(1));

    // 4. Reject EPOCH_CANNOT_GO_BACKWARD on advanceEpoch
    await expect(
      callCircuit(
        "advanceEpoch",
        createInitialPrivateState({ adminSecret }),
        initialEpoch - BigInt(10)
      )
    ).rejects.toThrow(/EPOCH_CANNOT_GO_BACKWARD/);

    // 5. Create USD Apartment Listing (mode 0: minIncome=7200, minBalance=4800)
    await callCircuit(
      "createListing",
      privateState,
      listingId,
      BigInt(0),
      BigInt(840),
      BigInt(7200),
      BigInt(4800)
    );

    // 6. Compute real Compact persistentHash commitment & test UNAUTHORIZED_ISSUER_KEY
    const honestCommit = computeCompactAttestationCommit({
      issuerId,
      applicantId,
      currency: BigInt(840),
      income: BigInt(9500),
      balance: BigInt(18000),
      attExpiry: validAttExpiry,
      nonce,
    });

    await expect(
      callCircuit(
        "anchorAttestation",
        createInitialPrivateState({ issuerSecret: wrongIssuerSecret }),
        issuerId,
        honestCommit
      )
    ).rejects.toThrow(/UNAUTHORIZED_ISSUER_KEY/);

    // 7. Real issuer anchors attestation on public ledger
    await callCircuit(
      "anchorAttestation",
      createInitialPrivateState({ issuerSecret }),
      issuerId,
      honestCommit
    );

    // 8. Attack: Tenant inflates salary locally -> TAMPERED_COMMITMENT
    await expect(
      callCircuit(
        "submitQualificationProof",
        createInitialPrivateState({
          tenantSecret,
          applicantIdCommit: applicantId,
          monthlyIncomeUsd: BigInt(95_000),
          liquidBalanceUsd: BigInt(18_000),
          attestationCurrency: BigInt(840),
          attestationIssuerId: issuerId,
          attestationExpiryEpoch: validAttExpiry,
          attestationNonce: nonce,
        }),
        listingId,
        BigInt(1)
      )
    ).rejects.toThrow(/TAMPERED_COMMITMENT/);

    // 9. Attack: Wrong currency (EUR 978 on USD 840 listing) -> CURRENCY_MISMATCH
    await expect(
      callCircuit(
        "submitQualificationProof",
        createInitialPrivateState({
          tenantSecret,
          applicantIdCommit: applicantId,
          monthlyIncomeUsd: BigInt(9500),
          liquidBalanceUsd: BigInt(18000),
          attestationCurrency: BigInt(978),
          attestationIssuerId: issuerId,
          attestationExpiryEpoch: validAttExpiry,
          attestationNonce: nonce,
        }),
        listingId,
        BigInt(1)
      )
    ).rejects.toThrow(/CURRENCY_MISMATCH/);

    // 10. Honest Tenant Proof Submission -> returns listing-bound receiptId & updates ledger
    const tenantPs = createInitialPrivateState({
      tenantSecret,
      applicantIdCommit: applicantId,
      monthlyIncomeUsd: BigInt(9500),
      liquidBalanceUsd: BigInt(18000),
      attestationCurrency: BigInt(840),
      attestationIssuerId: issuerId,
      attestationExpiryEpoch: validAttExpiry,
      attestationNonce: nonce,
    });
    const proofRes = await callCircuit("submitQualificationProof", tenantPs, listingId, BigInt(1));
    const receiptId: Uint8Array = proofRes.result;
    expect(receiptId).toBeInstanceOf(Uint8Array);
    expect(receiptId.length).toBe(32);

    expect(readLedger().verifiedReceipts.lookup(receiptId)).toBe(BigInt(1));
    expect(readLedger().totalVerifiedPasses).toBe(BigInt(1));

    // 11. Attack: Replay with rotated tenantSecret in same window -> REPLAY_ATTACK
    await expect(
      callCircuit(
        "submitQualificationProof",
        createInitialPrivateState({
          ...tenantPs,
          tenantSecret: padBytes32("rotated-secret-spam"),
        }),
        listingId,
        BigInt(1)
      )
    ).rejects.toThrow(/REPLAY_ATTACK/);

    // 12. Attack: Stranger tries to revoke tenant's pass -> UNAUTHORIZED_REVOKE
    await expect(
      callCircuit(
        "revokeReceipt",
        createInitialPrivateState({ tenantSecret: strangerSecret }),
        receiptId
      )
    ).rejects.toThrow(/UNAUTHORIZED_REVOKE/);

    // 13. Honest Tenant revokes their own pass -> status flips to REVOKED (2)
    await callCircuit(
      "revokeReceipt",
      createInitialPrivateState({ tenantSecret }),
      receiptId
    );
    expect(readLedger().verifiedReceipts.lookup(receiptId)).toBe(BigInt(2));
  });
});
